<?php
require_once __DIR__ . '/includes/functions.php';
if(!cart()){header('Location: cart.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$whatsapp=trim($_POST['whatsapp']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$address=trim($_POST['address']??'');$payment=in_array($_POST['payment']??'',['Cash on Delivery','M-Pesa on confirmation'],true)?$_POST['payment']:''; if(!$name||!$phone||!$whatsapp||!$email||!$address||!$payment){flash('error','Please complete all checkout fields.');}else{try{$pdo=db();$pdo->beginTransaction();$ids=array_keys(cart());$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,price,stock FROM products WHERE id IN ($marks) FOR UPDATE");$s->execute($ids);$products=[];foreach($s as $p)$products[$p['id']]=$p;$total=0;foreach(cart() as $id=>$qty){if(empty($products[$id])||$qty<1||$qty>$products[$id]['stock'])throw new RuntimeException('One or more phones are no longer available in the requested quantity.');$total+=$products[$id]['price']*$qty;}$s=$pdo->prepare('INSERT INTO customers(full_name,phone,whatsapp,email,address) VALUES(?,?,?,?,?)');$s->execute([$name,$phone,$whatsapp,$email,$address]);$customer=(int)$pdo->lastInsertId();$number='CM-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare('INSERT INTO orders(order_number,customer_id,total,payment_method,status) VALUES(?,?,?,?,"Pending")');$s->execute([$number,$customer,$total,$payment]);$order=(int)$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity) VALUES(?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach(cart() as $id=>$qty){$p=$products[$id];$line->execute([$order,$id,$p['name'],$p['price'],$qty]);$stock->execute([$qty,$id]);}$pdo->commit();$_SESSION['cart']=[];$_SESSION['order_number']=$number;header('Location: order-confirmation.php');exit;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}}}
$page_title='Checkout';require 'includes/header.php';?><section class="section"><div class="container checkout"><p class="eyebrow">Secure checkout</p><h1>Delivery details</h1><p>Order total: <strong><?=money(cart_total())?></strong></p><form class="checkout-form" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Full name<input required name="full_name" maxlength="120"></label><label>Phone number<input required name="phone" maxlength="30"></label><label>WhatsApp number<input required name="whatsapp" maxlength="30"></label><label>Email<input required type="email" name="email" maxlength="190"></label><label>Delivery location / address<textarea required name="address" maxlength="1000"></textarea></label><label>Payment / delivery option<select name="payment"><option>Cash on Delivery</option><option>M-Pesa on confirmation</option></select></label><button class="button primary">Place order</button></form></div></section><?php require 'includes/footer.php'; ?>
